// tier 4+ bir önceki kademenin eşyasını yükseltir
function tierCost(tier, base, white, up) {
  if (tier < 3) return { [MATS[tier].key]: base };
  if (tier === 3) return { whiteBar: 1, diamond: white };
  return { [MATS[tier].key]: up };
}

