    ctx.fillStyle = stone; ctx.fillRect(x - 80, g - 12, 160, 12); ctx.fillRect(x - 74, g - h, 148, 10);
    for (let k = -64; k <= 64; k += 21) ctx.fillRect(x + k - 5, g - h + 10, 10, h - 22);
