    if (r.workers < RESTO_MAX_WORKERS) uiButton(x + 230, y + 140, 200, 36, `İŞÇİ AL · ${RESTO_WORKER_PRICE} TL`, hireWorker, { bg: '#1565c0', font: 'bold 14px system-ui, sans-serif' });
