  ctx.fillStyle = '#ffd54f'; for (let k = 0; k < 5; k++) { ctx.beginPath(); ctx.moveTo(cx - 12 + k * 6, top + 2); ctx.lineTo(cx - 9 + k * 6, top - 8); ctx.lineTo(cx - 6 + k * 6, top + 2); ctx.fill(); } // taç
