  ctx.fillStyle = 'rgba(255,255,255,0.06)';
  roundRect(bx, y + 238, 260, 80, 10);
  ctx.fill();
  itemIcon('fish', bx + 22, y + 262, 9);
  text('Taze Balık', bx + 42, y + 267, 'bold 14px system-ui, sans-serif', '#fff');
