  flat(-400, CITY_SEA, 400, CITY_SEA + 300, '#1e88e5');
  for (let k = 0; k < 6; k++) { const wz = CITY_SEA + 6 + k * 14 + (city.t * 3) % 14; flat(-400, wz, 400, wz + 0.6, '#64b5f6'); }
  flat(-5, CITY_SEA - 2, 5, CITY_SEA + 34, '#8d6e63');
  flat(-4, 84, 4, CITY_SOUTH + 4, '#616161');
