    flat(p.x - 0.3, p.z - hd, p.x + 0.3, p.z + hd, '#ffffff');
    flat(p.x - hw, p.z - 5, p.x - hw + 5, p.z + 5, '#66bb6a');
    flat(p.x + hw - 5, p.z - 5, p.x + hw, p.z + 5, '#66bb6a');
