    for (let k = 0; k < 8; k++) { const a = city.t * 0.6 + k * Math.PI / 4; box(C, faces, lp.x + Math.cos(a) * 8, lp.z, 2, 2, 2, ['#e53935', '#fdd835', '#43a047', '#1e88e5'][k % 4], 9 + Math.sin(a) * 8); }
    box(C, faces, lp.x, lp.z, 1, 1, 10, '#90a4ae');
